import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Input, TextArea, Select, Modal } from '../../../components';

/**
 * CreateClaim - หน้าเปิดเคสเคลมใหม่
 * 
 * Features:
 * 1. กรอกข้อมูลลูกค้า
 * 2. กรอกข้อมูลรถยนต์
 * 3. กรอกข้อมูลเหตุการณ์
 * 4. มอบหมายพนักงาน
 * 
 * TODO: Backend Integration
 * - POST /api/insurance/claims - สร้างเคสใหม่
 * - GET /api/insurance/officers - ดึงรายชื่อพนักงาน
 */
const CreateClaim = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    // ข้อมูลลูกค้า
    customerName: '',
    customerPhone: '',
    customerEmail: '',
    policyNumber: '',
    
    // ข้อมูลรถยนต์
    carBrand: '',
    carModel: '',
    carYear: '',
    licensePlate: '',
    chassisNumber: '',
    
    // ข้อมูลเหตุการณ์
    incidentDate: '',
    incidentTime: '',
    location: '',
    description: '',
    
    // การมอบหมาย
    assignedOfficer: '',
    priority: 'normal',
  });
  const [errors, setErrors] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [newClaimId, setNewClaimId] = useState(null);

  // TODO: Backend - ดึงรายชื่อพนักงาน
  const officers = [
    { value: '1', label: 'นางสาววิภา ประกันภัย', icon: 'person' },
    { value: '2', label: 'นายสมชาย ตรวจสอบ', icon: 'person' },
    { value: '3', label: 'นางสุดา รายงาน', icon: 'person' },
  ];

  const priorityOptions = [
    { value: 'urgent', label: 'ด่วนมาก', icon: 'priority_high' },
    { value: 'high', label: 'ด่วน', icon: 'arrow_upward' },
    { value: 'normal', label: 'ปกติ', icon: 'remove' },
  ];

  const carBrands = [
    { value: 'honda', label: 'Honda', icon: 'directions_car' },
    { value: 'toyota', label: 'Toyota', icon: 'directions_car' },
    { value: 'mazda', label: 'Mazda', icon: 'directions_car' },
    { value: 'nissan', label: 'Nissan', icon: 'directions_car' },
    { value: 'mitsubishi', label: 'Mitsubishi', icon: 'directions_car' },
    { value: 'other', label: 'อื่นๆ', icon: 'more_horiz' },
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
  };

  const validate = () => {
    const newErrors = {};
    
    // ข้อมูลลูกค้า
    if (!formData.customerName || formData.customerName.trim().length < 3) {
      newErrors.customerName = 'กรุณากรอกชื่อลูกค้า (อย่างน้อย 3 ตัวอักษร)';
    }
    if (!formData.customerPhone || !/^[0-9]{9,10}$/.test(formData.customerPhone.replace(/-/g, ''))) {
      newErrors.customerPhone = 'กรุณากรอกเบอร์โทรศัพท์ให้ถูกต้อง (9-10 หลัก)';
    }
    if (!formData.policyNumber) {
      newErrors.policyNumber = 'กรุณากรอกเลขกรมธรรม์';
    }
    
    // ข้อมูลรถยนต์
    if (!formData.carBrand) {
      newErrors.carBrand = 'กรุณาเลือกยี่ห้อรถ';
    }
    if (!formData.carModel) {
      newErrors.carModel = 'กรุณากรอกรุ่นรถ';
    }
    if (!formData.licensePlate) {
      newErrors.licensePlate = 'กรุณากรอกทะเบียนรถ';
    }
    
    // ข้อมูลเหตุการณ์
    if (!formData.incidentDate) {
      newErrors.incidentDate = 'กรุณาเลือกวันที่เกิดเหตุ';
    }
    if (!formData.location || formData.location.trim().length < 10) {
      newErrors.location = 'กรุณากรอกสถานที่เกิดเหตุ (อย่างน้อย 10 ตัวอักษร)';
    }
    if (!formData.description || formData.description.trim().length < 20) {
      newErrors.description = 'กรุณาอธิบายเหตุการณ์ (อย่างน้อย 20 ตัวอักษร)';
    }
    
    // การมอบหมาย
    if (!formData.assignedOfficer) {
      newErrors.assignedOfficer = 'กรุณามอบหมายพนักงาน';
    }
    
    return newErrors;
  };

  // TODO: Backend - สร้างเคสใหม่
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const newErrors = validate();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    
    setSubmitting(true);
    
    setTimeout(() => {
      console.log('Create claim:', formData);
      const claimId = 'CLM-2024-' + Math.floor(Math.random() * 1000).toString().padStart(3, '0');
      setNewClaimId(claimId);
      setSubmitting(false);
      setShowSuccessModal(true);
    }, 1500);
  };

  const handleCloseSuccessModal = () => {
    setShowSuccessModal(false);
    navigate('/insurance/claims/active');
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <button
          onClick={() => navigate(-1)}
          className="inline-flex items-center gap-2 text-neutral-500 hover:text-primary-500 mb-3 transition-colors duration-300"
        >
          <span className="material-icons-round">arrow_back</span>
          <span>กลับ</span>
        </button>
        <h1 className="text-3xl font-bold text-neutral-dark mb-2">
          เปิดเคสเคลมใหม่
        </h1>
        <p className="text-neutral-500">
          กรอกข้อมูลเพื่อเปิดเคสเคลมประกันภัยใหม่
        </p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Form */}
        <div className="lg:col-span-2 space-y-6">
          {/* ข้อมูลลูกค้า */}
          <div className="card-static">
            <h2 className="text-xl font-semibold text-neutral-dark mb-4 flex items-center gap-2">
              <span className="material-icons-round text-primary-500">person</span>
              <span>ข้อมูลลูกค้า</span>
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Input
                label="ชื่อลูกค้า"
                name="customerName"
                value={formData.customerName}
                onChange={handleChange}
                placeholder="นายสมชาย ใจดี"
                icon="badge"
                required
                error={errors.customerName}
              />
              
              <Input
                label="เบอร์โทรศัพท์"
                name="customerPhone"
                type="tel"
                value={formData.customerPhone}
                onChange={handleChange}
                placeholder="081-234-5678"
                icon="phone"
                required
                error={errors.customerPhone}
              />
              
              <Input
                label="อีเมล (ถ้ามี)"
                name="customerEmail"
                type="email"
                value={formData.customerEmail}
                onChange={handleChange}
                placeholder="customer@example.com"
                icon="email"
                error={errors.customerEmail}
              />
              
              <Input
                label="เลขกรมธรรม์"
                name="policyNumber"
                value={formData.policyNumber}
                onChange={handleChange}
                placeholder="POL-2024-001234"
                icon="description"
                required
                error={errors.policyNumber}
              />
            </div>
          </div>

          {/* ข้อมูลรถยนต์ */}
          <div className="card-static">
            <h2 className="text-xl font-semibold text-neutral-dark mb-4 flex items-center gap-2">
              <span className="material-icons-round text-primary-500">directions_car</span>
              <span>ข้อมูลรถยนต์</span>
            </h2>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Select
                label="ยี่ห้อรถ"
                name="carBrand"
                value={formData.carBrand}
                onChange={handleChange}
                options={carBrands}
                icon="directions_car"
                required
                error={errors.carBrand}
                placeholder="เลือกยี่ห้อรถ"
              />
              
              <Input
                label="รุ่นรถ"
                name="carModel"
                value={formData.carModel}
                onChange={handleChange}
                placeholder="City, Yaris, CX-5..."
                icon="directions_car"
                required
                error={errors.carModel}
              />
              
              <Input
                label="ปีที่จดทะเบียน"
                name="carYear"
                type="number"
                value={formData.carYear}
                onChange={handleChange}
                placeholder="2020"
                icon="calendar_today"
                error={errors.carYear}
              />
              
              <Input
                label="ทะเบียนรถ"
                name="licensePlate"
                value={formData.licensePlate}
                onChange={handleChange}
                placeholder="กข 1234 กรุงเทพ"
                icon="pin"
                required
                error={errors.licensePlate}
              />
              
              <div className="md:col-span-2">
                <Input
                  label="เลขตัวถัง (ถ้ามี)"
                  name="chassisNumber"
                  value={formData.chassisNumber}
                  onChange={handleChange}
                  placeholder="JHMC12345678"
                  icon="tag"
                  error={errors.chassisNumber}
                />
              </div>
            </div>
          </div>

          {/* ข้อมูลเหตุการณ์ */}
          <div className="card-static">
            <h2 className="text-xl font-semibold text-neutral-dark mb-4 flex items-center gap-2">
              <span className="material-icons-round text-primary-500">event_note</span>
              <span>ข้อมูลเหตุการณ์</span>
            </h2>
            
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Input
                  label="วันที่เกิดเหตุ"
                  name="incidentDate"
                  type="date"
                  value={formData.incidentDate}
                  onChange={handleChange}
                  icon="calendar_today"
                  required
                  error={errors.incidentDate}
                />
                
                <Input
                  label="เวลาที่เกิดเหตุ (ประมาณ)"
                  name="incidentTime"
                  type="time"
                  value={formData.incidentTime}
                  onChange={handleChange}
                  icon="schedule"
                  error={errors.incidentTime}
                />
              </div>
              
              <Input
                label="สถานที่เกิดเหตุ"
                name="location"
                value={formData.location}
                onChange={handleChange}
                placeholder="123 ถนนประชาราษฎร์ แขวงห้วยขวาง เขตห้วยขวาง กรุงเทพมหานคร"
                icon="location_on"
                required
                error={errors.location}
              />
              
              <TextArea
                label="รายละเอียดเหตุการณ์"
                name="description"
                value={formData.description}
                onChange={handleChange}
                placeholder="อธิบายเหตุการณ์ที่เกิดขึ้น เช่น ชนด้านหน้าจากรถที่วิ่งสวนทาง..."
                rows={6}
                required
                error={errors.description}
              />
            </div>
          </div>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* การมอบหมาย */}
          <div className="card-static">
            <h3 className="font-semibold text-neutral-dark mb-4 flex items-center gap-2">
              <span className="material-icons-round text-primary-500">person_add</span>
              <span>การมอบหมาย</span>
            </h3>
            
            <div className="space-y-4">
              <Select
                label="พนักงานที่รับผิดชอบ"
                name="assignedOfficer"
                value={formData.assignedOfficer}
                onChange={handleChange}
                options={officers}
                icon="person"
                required
                error={errors.assignedOfficer}
                placeholder="เลือกพนักงาน"
              />
              
              <div>
                <label className="block mb-3 text-sm font-medium text-neutral-700">
                  ระดับความเร่งด่วน <span className="text-error">*</span>
                </label>
                <div className="space-y-2">
                  {priorityOptions.map(option => (
                    <label
                      key={option.value}
                      className={`
                        flex items-center gap-3 p-3 border-2 rounded-lg cursor-pointer transition-all duration-300
                        ${formData.priority === option.value
                          ? 'border-primary-500 bg-primary-50'
                          : 'border-neutral-200 hover:border-primary-300'
                        }
                      `}
                    >
                      <input
                        type="radio"
                        name="priority"
                        value={option.value}
                        checked={formData.priority === option.value}
                        onChange={handleChange}
                        className="sr-only"
                      />
                      <span className={`
                        material-icons-round
                        ${formData.priority === option.value
                          ? 'text-primary-600'
                          : 'text-neutral-400'
                        }
                      `}>
                        {option.icon}
                      </span>
                      <span className={`
                        flex-1 font-medium text-sm
                        ${formData.priority === option.value
                          ? 'text-primary-700'
                          : 'text-neutral-700'
                        }
                      `}>
                        {option.label}
                      </span>
                    </label>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Info Card */}
          <div className="card bg-gradient-primary text-white">
            <span className="material-icons-round text-4xl mb-3">info</span>
            <h3 className="font-semibold mb-2">ข้อมูลสำคัญ</h3>
            <p className="text-sm text-white/80 mb-4">
              หลังจากเปิดเคส พนักงานที่ได้รับมอบหมายจะต้องลงพื้นที่ตรวจสอบและอัปโหลดรายงานภายใน 24-48 ชั่วโมง
            </p>
          </div>

          {/* Submit */}
          <div className="space-y-3">
            <button
              type="submit"
              className="btn-primary w-full"
              disabled={submitting}
            >
              {submitting ? (
                <>
                  <span className="material-icons-round animate-spin mr-2">refresh</span>
                  กำลังสร้างเคส...
                </>
              ) : (
                <>
                  <span className="material-icons-round mr-2">check_circle</span>
                  เปิดเคส
                </>
              )}
            </button>
            <button
              type="button"
              onClick={() => navigate(-1)}
              className="btn-outline w-full"
              disabled={submitting}
            >
              ยกเลิก
            </button>
          </div>
        </div>
      </form>

      {/* Success Modal */}
      <Modal
        isOpen={showSuccessModal}
        onClose={handleCloseSuccessModal}
        title="เปิดเคสสำเร็จ"
        size="md"
        footer={
          <button
            onClick={handleCloseSuccessModal}
            className="btn-primary w-full"
          >
            เข้าใจแล้ว
          </button>
        }
      >
        <div className="text-center py-4">
          <div className="w-16 h-16 bg-success/10 rounded-full flex items-center justify-center mx-auto mb-4">
            <span className="material-icons-round text-4xl text-success">
              check_circle
            </span>
          </div>
          <p className="text-lg font-semibold text-neutral-dark mb-2">
            เปิดเคสสำเร็จ
          </p>
          <p className="text-neutral-600 mb-4">
            เลขที่เคลม: <span className="font-semibold text-primary-600">{newClaimId}</span>
          </p>
          <div className="p-4 bg-blue-50 rounded-lg text-left">
            <p className="text-sm text-neutral-700">
              <span className="material-icons-round text-sm mr-1 align-middle text-info">info</span>
              พนักงานที่ได้รับมอบหมายจะได้รับการแจ้งเตือนทันที
            </p>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default CreateClaim;
